+    final roomId = int.tryParse(selected['id']?.toString() ?? '');
+    if (roomId == null) {
+      ScaffoldMessenger.of(context).showSnackBar(
+        const SnackBar(content: Text('That chat does not have a valid room id.')),
+      );
+      return;
+    }
+    final meetings = context.read<AppServices>().meetings;
+    try {
+      final meeting = await meetings.createMeeting(
+            chatRoomId: roomId,
+            projectId: int.tryParse(selected['project_id']?.toString() ?? ''),
+            title: '${selected['name'] ?? 'Team'} meeting',
+          ).unwrap();
+      if (!mounted) return;
+      await Navigator.push(
+        context,
+        MaterialPageRoute(
+          builder: (_) => MeetingPreviewScreen(publicId: meeting.publicId),
+        ),
+      );
+      await _load();
+    } catch (e, st) {
+      AppLogger.error('Create meeting failed', e, st);
+      if (mounted) {
+        ScaffoldMessenger.of(context).showSnackBar(
+          SnackBar(content: Text('Could not create meeting: $e')),
+        );
+      }
+    }
+  }
+
+  Future<void> _open(ApiMeeting meeting) async {
+    if (meeting.isEnded) {
+      Map<String, dynamic>? session = meeting.session;
+      if (session == null) {
+        final result =
+            await context.read<AppServices>().meetings.getMeeting(meeting.publicId);
+        if (result.isSuccess && result.data?.session != null) {
+          session = result.data!.session;
+        }
+      }
+      if (!mounted) return;
+      Navigator.push(
+        context,
+        MaterialPageRoute(
+          builder: (_) => MeetingSummaryScreen(
+            roomName: meeting.title,
+            roomId: meeting.chatRoomId,
+            projectId: meeting.projectId,
+            initialSession: session,
+          ),
+        ),
+      );
+      return;
+    }
+    Navigator.push(
+      context,
+      MaterialPageRoute(
+        builder: (_) => MeetingPreviewScreen(publicId: meeting.publicId),
+      ),
+    ).then((_) => _load());
+  }
+
+  @override
+  Widget build(BuildContext context) {
+    return Scaffold(
+      backgroundColor: Colors.white,
+      appBar: AppBar(
+        title: const Text(
+          'Meetings',
+          style: TextStyle(fontWeight: FontWeight.bold, fontSize: 20),
+        ),
+        actions: [
+          IconButton(
+            icon: const Icon(Icons.add_call),
+            onPressed: _createFromChat,
+            tooltip: 'Start meeting',
+          ),
+        ],
+      ),
+      body: Column(
+        children: [
+          Padding(
+            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
+            child: Row(
+              children: [
+                _chip('All'),
+                const SizedBox(width: 8),
+                _chip('Upcoming'),
+                const SizedBox(width: 8),
+                _chip('Ended'),
+              ],
+            ),
+          ),
+          Expanded(
+            child: _loading
+                ? const Center(child: CircularProgressIndicator())
+                : _error != null
+                    ? Center(
+                        child: Column(
+                          mainAxisSize: MainAxisSize.min,
+                          children: [
+                            Text(_error!,
+                                style: const TextStyle(
+                                    color: AppColors.textSecondary)),
+                            const SizedBox(height: 12),
+                            ElevatedButton(
+                                onPressed: _load, child: const Text('Retry')),
+                          ],
+                        ),
+                      )
+                    : RefreshIndicator(
+                        onRefresh: _load,
+                        child: _filtered.isEmpty
+                            ? ListView(
+                                children: const [
+                                  SizedBox(height: 80),
+                                  Center(
+                                    child: Text(
+                                      'No meetings yet. Start one from Team Chat or a DM.',
+                                      textAlign: TextAlign.center,
+                                    ),
+                                  ),
+                                ],
+                              )
+                            : ListView.builder(
+                                padding: const EdgeInsets.symmetric(
+                                    horizontal: 16, vertical: 8),
+                                itemCount: _filtered.length,
+                                itemBuilder: (_, i) =>
+                                    _card(_filtered[i]),
+                              ),
+                      ),
+          ),
+        ],
+      ),
+    );
+  }
+
+  Widget _chip(String label) {
+    final selected = _tab == label;
+    return ChoiceChip(
+      label: Text(label),
+      selected: selected,
+      onSelected: (_) => setState(() => _tab = label),
+    );
+  }
+
+  Widget _card(ApiMeeting m) {
+    final when = m.startsAt ?? m.createdAt ?? '';
+    return Card(
+      margin: const EdgeInsets.only(bottom: 12),
+      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
+      child: Padding(
+        padding: const EdgeInsets.all(16),
+        child: Column(
+          crossAxisAlignment: CrossAxisAlignment.start,
+          children: [
+            Row(
+              children: [
+                Expanded(
+                  child: Text(
+                    m.title,
+                    style: const TextStyle(
+                        fontWeight: FontWeight.bold, fontSize: 16),
+                  ),
+                ),
+                _statusPill(m),
+              ],
+            ),
+            const SizedBox(height: 8),
+            Text(
+              [
+                if (m.hostName.isNotEmpty) 'Host: ${m.hostName}',
+                if ((m.projectName ?? '').isNotEmpty) m.projectName!,
+                if (when.isNotEmpty) formatRelativeTime(when),
+                '${m.participantCount} participants',
+              ].join(' · '),
+              style: const TextStyle(
+                  color: AppColors.textSecondary, fontSize: 13),
+            ),
+            const SizedBox(height: 12),
+            Align(
+              alignment: Alignment.centerRight,
+              child: ElevatedButton(
+                onPressed: () => _open(m),
+                style: ElevatedButton.styleFrom(
+                  backgroundColor:
+                      m.isLive ? AppColors.success : AppColors.primary,
+                  foregroundColor: Colors.white,
+                ),
+                child: Text(m.isEnded ? 'View summary' : 'Join'),
+              ),
+            ),
+          ],
+        ),
+      ),
+    );
+  }
+
+  Widget _statusPill(ApiMeeting m) {
+    final color = m.isLive
+        ? AppColors.success
+        : m.isEnded
+            ? AppColors.textSecondary
+            : AppColors.primary;
+    return Container(
+      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
+      decoration: BoxDecoration(
+        color: color.withValues(alpha: 0.12),
+        borderRadius: BorderRadius.circular(10),
+      ),
+      child: Text(
+        m.status.toUpperCase(),
+        style: TextStyle(
+            color: color, fontSize: 11, fontWeight: FontWeight.bold),
+      ),
+    );
+  }
+}

